titulo: "🦠 Poríferos",

conteudo: `

<h2 style="color:#00ff88;">🦠 Introdução aos Poríferos</h2>

<p>
Os poríferos são os animais mais simples do Reino Animal. O nome do grupo vem da presença de inúmeros poros espalhados pelo corpo. As esponjas-do-mar são os principais representantes desse filo.
</p>

<p>
Os poríferos vivem principalmente em ambientes marinhos, embora algumas espécies sejam encontradas em água doce.
</p>

<div class="caixa-exemplo">
📌 Exemplo: as esponjas encontradas fixadas em rochas no fundo do mar pertencem ao grupo dos poríferos.
</div>

<h2 style="color:#00ff88;">🏛 Principais Características</h2>

<p>
Os poríferos apresentam uma organização corporal extremamente simples quando comparados aos demais animais.
</p>

<table>
<tr>
<th>Característica</th>
<th>Descrição</th>
</tr>

<tr>
<td>Pluricelulares</td>
<td>Possuem muitas células.</td>
</tr>

<tr>
<td>Eucariontes</td>
<td>Células com núcleo definido.</td>
</tr>

<tr>
<td>Heterotróficos</td>
<td>Não produzem seu próprio alimento.</td>
</tr>

<tr>
<td>Aquáticos</td>
<td>Vivem na água.</td>
</tr>

<tr>
<td>Sésseis</td>
<td>Vivem fixos ao substrato.</td>
</tr>

<tr>
<td>Assimétricos</td>
<td>Não apresentam padrão corporal definido.</td>
</tr>
</table>

<h2 style="color:#00ff88;">🔬 Organização Corporal</h2>

<p>
Os poríferos não possuem tecidos verdadeiros, órgãos ou sistemas. Suas células realizam as funções vitais de maneira relativamente independente.
</p>

<div class="caixa-destaque">

Poríferos

⬇️

Não possuem tecidos

⬇️

Não possuem órgãos

⬇️

Não possuem sistemas

⬇️

Organização simples

</div>

<p>
Essa simplicidade faz dos poríferos os animais menos complexos do Reino Animal.
</p>

<h2 style="color:#00ff88;">🕳 Os Poros e o Fluxo de Água</h2>

<p>
O corpo das esponjas é repleto de pequenos poros chamados óstios. A água entra por esses poros, circula pelo interior do animal e sai por uma abertura maior chamada ósculo.
</p>

<div class="caixa-destaque">

Água entra

⬇️

Óstios (poros)

⬇️

Cavidade interna

⬇️

Ósculo

⬇️

Água sai

</div>

<p>
Esse fluxo constante de água permite a obtenção de alimento e oxigênio.
</p>

<h2 style="color:#00ff88;">🧫 Coanócitos</h2>

<p>
Os coanócitos são células especializadas que revestem parte do interior das esponjas.
</p>

<p>
Essas células possuem flagelos que movimentam a água e ajudam na captura de partículas alimentares.
</p>

<div class="caixa-exemplo">
📌 Os coanócitos funcionam como pequenas bombas biológicas, mantendo a circulação da água dentro da esponja.
</div>

<table>
<tr>
<th>Estrutura</th>
<th>Função</th>
</tr>

<tr>
<td>Coanócito</td>
<td>Movimentar água e capturar alimento.</td>
</tr>

<tr>
<td>Óstio</td>
<td>Entrada da água.</td>
</tr>

<tr>
<td>Ósculo</td>
<td>Saída da água.</td>
</tr>
</table>

<h2 style="color:#00ff88;">🍽 Alimentação</h2>

<p>
Os poríferos são animais filtradores. Eles retiram da água pequenas partículas orgânicas e micro-organismos que servem como alimento.
</p>

<div class="caixa-destaque">

Água

⬇️

Partículas alimentares

⬇️

Coanócitos

⬇️

Digestão intracelular

</div>

<p>
A digestão ocorre dentro das células, sendo chamada de digestão intracelular.
</p>

<h2 style="color:#00ff88;">🌬 Respiração e Excreção</h2>

<p>
Os poríferos não possuem sistemas respiratório ou excretor.
</p>

<p>
As trocas gasosas e a eliminação de resíduos ocorrem por difusão diretamente entre as células e a água.
</p>

<table>
<tr>
<th>Função</th>
<th>Como ocorre</th>
</tr>

<tr>
<td>Respiração</td>
<td>Difusão</td>
</tr>

<tr>
<td>Excreção</td>
<td>Difusão</td>
</tr>

<tr>
<td>Circulação</td>
<td>Fluxo de água</td>
</tr>
</table>

<h2 style="color:#00ff88;">🧬 Reprodução</h2>

<p>
Os poríferos podem reproduzir-se de forma assexuada ou sexuada.
</p>

<table>
<tr>
<th>Tipo</th>
<th>Características</th>
</tr>

<tr>
<td>Assexuada</td>
<td>Brotamento e regeneração.</td>
</tr>

<tr>
<td>Sexuada</td>
<td>Produção de gametas.</td>
</tr>
</table>

<div class="caixa-exemplo">
📌 Uma pequena parte de uma esponja pode originar um novo indivíduo devido à grande capacidade de regeneração.
</div>

<h2 style="color:#00ff88;">⚠ Pegadinhas de Concurso</h2>

<p>❌ Poríferos possuem tecidos verdadeiros.</p>
<p>✅ Não possuem tecidos verdadeiros.</p>

<br>

<p>❌ Coanócitos realizam digestão extracelular.</p>
<p>✅ A digestão é intracelular.</p>

<br>

<p>❌ Esponjas possuem sistema digestório.</p>
<p>✅ Não possuem órgãos nem sistemas.</p>

<br>

<p>❌ Os poríferos são predadores ativos.</p>
<p>✅ São animais filtradores.</p>

<h3 style="color:#00ff88;">
🎯 Revisão da Página
</h3>

<div class="caixa-destaque">

Poríferos

⬇️

Esponjas

⬇️

Animais mais simples

⬇️

Sem tecidos

⬇️

Filtradores

⬇️

Coanócitos

⬇️

Água entra pelos óstios

⬇️

Água sai pelo ósculo

⬇️

Digestão intracelular

</div>

`

